1	export type Item = {
2	  type: string;
3	  material?: string;
4	  enchantment?: number;
5	  cursed?: boolean;
6	};
7	
8	export type Damage = {
9	  itemType: string;
10	  amount: number;
11	};
12	
13	export type Step =
14	  | { op: "quote"; items: Item[] }
15	  | { op: "claim"; policy: number; incident: { cause: string; damages: Damage[] } };
16	
17	export type Scenario = {
18	  customer: { yearsWithMHPCO: number };
19	  steps: Step[];
20	};
21	
22	export type Result = { premium: number } | { payout: number; remainingCap: number };
23	
24	const PROCESSING_FEE = 5;
25	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
26	const CURSE_SURCHARGE_RATE = 0.5;
27	
28	const BASE_PREMIUMS: Record<string, number> = {
29	  sword: 100,
30	  amulet: 60,
31	  staff: 80,
32	  potion: 40,
33	  rune: 25,
34	  moonstone: 25,
35	};
36	
37	const BLOCK_SIZE = 3;
38	const BLOCK_PREMIUM = 60;
39	
40	/** Items that share the same `type`, and so are priced together. */
41	type AlikeItems = { type: string; items: Item[] };
42	
43	const groupByType = (items: Item[]): AlikeItems[] => {
44	  const itemsByType = new Map<string, Item[]>();
45	  for (const item of items) {
46	    itemsByType.set(item.type, [...(itemsByType.get(item.type) ?? []), item]);
47	  }
48	  return [...itemsByType].map(([type, alike]) => ({ type, items: alike }));
49	};
50	
51	const formsBlock = (items: Item[]): boolean => items.length === BLOCK_SIZE;
52	
53	const itemBasePremium = (item: Item): number => BASE_PREMIUMS[item.type];
54	
55	const basePremiumFor = ({ items }: AlikeItems): number =>
56	  formsBlock(items)
57	    ? BLOCK_PREMIUM
58	    : items.reduce((total, item) => total + itemBasePremium(item), 0);
59	
60	const totalBasePremium = (items: Item[]): number =>
61	  groupByType(items).reduce((total, alike) => total + basePremiumFor(alike), 0);
62	
63	const totalCurseSurcharge = (items: Item[]): number =>
64	  items.reduce(
65	    (total, item) => (item.cursed ? total + itemBasePremium(item) * CURSE_SURCHARGE_RATE : total),
66	    0,
67	  );
68	
69	const quotePremium = (items: Item[]): number => {
70	  const base = totalBasePremium(items);
71	  // Keep the surcharge additive (base + base * rate). The algebraically
72	  // equivalent base * (1 + rate) yields 110.00000000000001 for base 100,
73	  // which Math.ceil turns into a premium that is 1 G too high.
74	  const firstInsuranceSurcharge = base * FIRST_INSURANCE_SURCHARGE_RATE;
75	  return Math.ceil(
76	    base + totalCurseSurcharge(items) + firstInsuranceSurcharge + PROCESSING_FEE,
77	  );
78	};
79	
80	export const runScenario = (scenario: Scenario): Result[] =>
81	  scenario.steps.map((step) => {
82	    if (step.op === "quote") return { premium: quotePremium(step.items) };
83	    throw new Error(`Unsupported step: ${step.op}`);
84	  });
