/**
 * Sums `rate` × base premium over the items that `applies` to. Item-specific
 * surcharges are charged on the item's own base premium, never on the policy's,
 * so each one is an independent additive term.
 */
const perItemSurcharge = (
  items: Item[],
  applies: (item: Item) => boolean,
  rate: number,
): number =>
  items
    .filter(applies)
    .reduce((total, item) => total + itemBasePremium(item) * rate, 0);

const isCursed = (item: Item): boolean => item.cursed === true;

const totalCurseSurcharge = (items: Item[]): number =>
  perItemSurcharge(items, isCursed, CURSE_SURCHARGE_RATE);
